"""Studio 2026 template pack — 16 additional industry templates authored in the new design system.

These reuse the same page builder as the original pack, so they get the CTA modal forms, locks,
overview sync and export pipeline for free. Each one is flagged `studio: True` so the gallery can
badge it as a new-design template and tenants created from it start on the new skin.
"""
from site_content import NICHES, LOOKS, MOODS, img  # noqa: F401

SECTIONS = ["services", "stats", "gallery", "testimonials", "team", "faq", "cta"]


def _mk(brand, industry, badge, title, sub, cta, cta2, hero, gallery, video,
        services, stats, quotes, faq, about, team, email, phone, address, mood="moody"):
    h, ssub, items = services
    return {
        "brand": brand, "industry": industry, "mood": mood, "badge": badge, "title": title, "sub": sub,
        "cta": cta, "cta2": cta2, "hero": img(hero), "video": video, "gallery": gallery,
        "sections": SECTIONS, "services": (h, ssub, items), "stats": stats, "quotes": quotes,
        "faq": faq, "about": about, "team": team, "email": email, "phone": phone, "address": address,
        "primary": "#4F46E5", "secondary": "#0EA5E9",
    }


def _vid(q):
    return f"https://www.youtube.com/embed?listType=search&list={q.replace(' ', '+')}"


