STUDIO_KEYS = tuple(k for k, _ in _T)


def install():
    """Register the Studio pack into the shared NICHES / LOOKS tables (idempotent)."""
    from site_content import LOOK_V
    for key, niche in _T:
        NICHES.setdefault(key, niche)
        if key in LOOKS:
            continue
        mode, p, s, bg, sf, bd, fg, mut, fh, fb, r, preset, hero = _LOOKS2[key]
        NICHES[key]["primary"], NICHES[key]["secondary"] = p, s
        LOOKS[key] = dict(mode=mode, primary=p, secondary=s, bg=bg, surface=sf, border=bd, fg=fg,
                          muted=mut, font_heading=fh, font_body=fb, radius=r, preset=preset,
                          hero=hero, glass=mode == "dark", grain=mode == "dark", studio=True,
                          look_v=LOOK_V)
    return len(_T)
